from __future__ import annotations

import pytest
from pydantic import BaseModel

from llm_router._internal.capabilities import (
    SchemaSpec,
    validate_schema_output,
)

pytestmark = pytest.mark.verification_kind("unit")


class VehicleTally(BaseModel):
    """Object result with an integer count."""

    count: int


def _parse_tally(raw: object) -> object:
    return VehicleTally.model_validate(raw).model_dump()


def _spec() -> SchemaSpec:
    return SchemaSpec(
        name="VehicleTally",
        json_schema=VehicleTally.model_json_schema(),
        parser=_parse_tally,
    )


@pytest.mark.verifies("REQ_STRUCTURED_TEXT_OUTPUT[revision==2]")
def test_decoded_dict_is_still_validated_and_normalised() -> None:
    """Pre-decoded dicts go through the schema parser, not around it."""
    spec = _spec()

    rejected = validate_schema_output(spec, {"count": "many"})
    assert rejected.valid is False
    assert rejected.error_message

    accepted = validate_schema_output(spec, {"count": "5"})
    assert accepted.valid is True
    assert accepted.value == {"count": 5}
